import fitz, numpy as np
d = fitz.open('eprint/boundsSK_g_vs_ma_8.pdf')
p = d[0]
dr = p.get_drawings()[5]
pts=[]
for it in dr['items']:
    if it[0]=='l':
        if not pts: pts.append(it[1])
        pts.append(it[2])
    elif it[0]=='c':
        if not pts: pts.append(it[1])
        pts.append(it[4])
xs = np.array([q.x for q in pts]); ys = np.array([q.y for q in pts])
ma = 10**((xs-70.15)/195.3)          # MeV
g  = 10**(-7 + (394.95-ys)/104.9)
print(len(ma))
print('first pts:'); 
for i in range(0,len(ma),max(1,len(ma)//40)):
    print('%.3f %.3e'%(ma[i],g[i]))
print('closed?', ma[0], ma[-1], g[0], g[-1])
np.save('sk_ma.npy', ma); np.save('sk_g.npy', g)
